params.command:
$ErrorActionPreference='Stop';
$repo='C:\Users\Xxkan\HeavenBridgeRepo';
$wt='C:\Users\Xxkan\local-ai-workspaces\heaven-bridge-exact-main-verify';
git -C $repo fetch origin main;
if($LASTEXITCODE -ne 0){throw 'fetch main failed'}
if(Test-Path $wt){git -C $repo worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue}
git -C $repo worktree add --detach $wt origin/main;
if($LASTEXITCODE -ne 0){throw 'worktree add failed'}
try {
  $sha=(git -C $wt rev-parse HEAD).Trim();
  Write-Output ('VERIFY_SHA='+$sha);
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $wt 'heaven-bridge\manage.ps1') TEST;
  if($LASTEXITCODE -ne 0){throw ('bridge gate failed exit '+$LASTEXITCODE)}
  Write-Output 'EXACT_MAIN_BRIDGE_GATE_OK';
} finally {
  git -C $repo worktree remove --force $wt 2>$null;
}
